class Thermostat:
    """Keeps a target temperature between 5 and 30 degrees."""

    def __init__(self, target):
        self.target = target          # uses the setter, so it's checked

    @property
    def target(self):
        return self._target

    @target.setter
    def target(self, value):
        if not 5 <= value <= 30:
            raise ValueError(f"target must be 5-30, not {value}")
        self._target = value

    @property
    def fahrenheit(self):             # read-only: no setter
        return self._target * 9 / 5 + 32


t = Thermostat(21)
t.target = 25
print(t.target, t.fahrenheit)
try:
    t.target = 90
except ValueError as e:
    print("refused:", e)
print(t.target)

