exercises.solution:
class MedicineStock:
    def __init__(self, name, count):
        self.name = name
        self.count = count            # through the setter: checked from the start

    @property
    def count(self):
        return self._count

    @count.setter
    def count(self, value):
        if not isinstance(value, int) or value < 0:
            raise ValueError(f"count must be a whole number 0 or more, not {value!r}")
        self._count = value

    def dispense(self, n):
        if n > self.count:
            raise ValueError(f"only {self.count} {self.name} left, can't give {n}")
        self.count -= n
        return self.count

tests.check:
try:
    MedicineStock('ORS', -3)
    raise AssertionError('MedicineStock("ORS", -3) should raise ValueError: set self.count in __init__')
except ValueError:
    pass

s = MedicineStock('ORS', 10)
for bad in [2.5, '10', None]:
    try:
        s.count = bad
        raise AssertionError('count = %r should raise ValueError' % (bad,))
    except ValueError:
        pass
assert s.count == 10

