exercises.solution:
class Tank:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be more than 0")
        self._capacity = capacity
        self.level = 0

    @property
    def capacity(self):
        return self._capacity

    @property
    def level(self):
        return self._level

    @level.setter
    def level(self, value):
        if not 0 <= value <= self._capacity:
            raise ValueError(f"level must be 0-{self._capacity}, not {value}")
        self._level = value

    @property
    def percent(self):
        return self._level / self._capacity * 100

tests.check:
t = Tank(1000)
try:
    t.capacity = 5000
    raise AssertionError('capacity should be read-only (a property with no setter)')
except AttributeError:
    pass

t = Tank(100)
for bad in [-1, 101]:
    try:
        t.level = bad
        raise AssertionError('level = %r should raise ValueError' % bad)
    except ValueError:
        pass
assert t.level == 0

for bad in [0, -5]:
    try:
        Tank(bad)
        raise AssertionError('Tank(%r) should raise ValueError' % bad)
    except ValueError:
        pass

