exercises.solution:
class Account:
    def __init__(self, owner):
        self.owner = owner
        self._balance = 0
        self._history = []

    @property
    def balance(self):
        return self._balance

    @property
    def history(self):
        return list(self._history)    # a copy: outside code can't edit our record

    def deposit(self, amount):
        if amount <= 0:
            raise ValueError("deposit must be more than 0")
        self._balance += amount
        self._history.append(("deposit", amount))

    def withdraw(self, amount):
        if amount <= 0:
            raise ValueError("withdrawal must be more than 0")
        if amount > self._balance:
            raise ValueError(f"only {self._balance} available")
        self._balance -= amount
        self._history.append(("withdraw", amount))

tests.check:
a = Account('Wanjiru')
a.deposit(100)
for bad in [(a.withdraw, 500), (a.deposit, 0), (a.deposit, -20), (a.withdraw, -5)]:
    try:
        bad[0](bad[1])
        raise AssertionError('%s(%r) should raise ValueError' % (bad[0].__name__, bad[1]))
    except ValueError:
        pass
assert a.balance == 100 and a.history == [('deposit', 100)], 'a refused action must change nothing'

a = Account('Wanjiru')
try:
    a.balance = 1000000
    raise AssertionError('balance should be read-only')
except AttributeError:
    pass
